#include <PrivateShopsSql.hpp>
#include <item/PrivateShopWire.hpp>
#include <item/NativeMoney.hpp>
void PrivateShopCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,const std::string& password,const std::string& path,const std::vector<BulkSource>& sources){
 using namespace auriga::item;Check(sources.size()==2,"both original private shop permits present");ItemKey paper=sources[0].grant.key,silk=paper;for(const auto& row:sources){if(PrivateShopPermit(*catalog,row.grant.key)==PrivateShopPermitKind::Consumed)paper=row.grant.key;else silk=row.grant.key;}
 Check(PrivateShopPermit(*catalog,paper)==PrivateShopPermitKind::Consumed && PrivateShopPermit(*catalog,silk)==PrivateShopPermitKind::Silk,"distinct original paper and ten-day silk roles loaded");
 CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"owned shop SQL connects");
 auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-private-shop-worker").has_value(),"real shop store starts");
 constexpr std::uint64_t cap=999000000000ULL,price=7000000001ULL;const ItemOwner seller{ItemOwnerKind::Character,24001},buyer{ItemOwnerKind::Character,24002},other{ItemOwnerKind::Character,24003};
 for(const auto owner:{seller,buyer,other}){const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,3}};const std::array wallets{ItemWallet{owner,WalletCurrency::Gold,1,owner==seller?1000ULL:50000000000ULL}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,wallets).has_value(),"shop participant provisioned");}
 auto state=persistence::LoadCurrentItemOwner(sql,*catalog,seller).value(),buy=persistence::LoadCurrentItemOwner(sql,*catalog,buyer).value(),third=persistence::LoadCurrentItemOwner(sql,*catalog,other).value();unsigned serial=0,packets=0;bool replay=false;
 const auto now=[](){return static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());};
 const auto op=[&](){++serial;return std::array<std::uint8_t,16>{0x57,static_cast<std::uint8_t>(serial),static_cast<std::uint8_t>(serial>>8)};};
 const auto wait=[&](const auto& ready){for(unsigned n=0;!ready() && n<2000;++n){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(5));}Check(ready(),"shop store completion returned");};
 const auto apply=[&](const ItemCommit& commit,bool expect=true){std::vector<runtime::OwnerRead> reads;for(const auto& f:commit.owners)reads.push_back({f.owner,f.sessionGeneration});std::optional<runtime::MultiCommitOutcome> out;Check(runtime::RequestCommitMany(reads,commit,[&](auto result){out=std::move(result);}),"shop write queued");wait([&](){return out.has_value();});if(out->write.has_value()!=expect)std::cerr<<"SHOP_SQL_ERROR="<<(out->write?-1:static_cast<int>(out->write.error()))<<" serial="<<serial<<'\n';Check(out->write.has_value()==expect,"shop SQL write matches expected result");replay=out->write && out->write->replay;for(auto& s:out->states)if(s){if(s->fence.owner==seller)state=std::move(*s);else if(s->fence.owner==buyer)buy=std::move(*s);else third=std::move(*s);}};
 std::uint64_t nextId=80000000;
 const auto grant=[&](ItemGrant g){const std::array ids{ItemInstanceId::Create(++nextId).value()};auto r=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,g,ids);Check(r.has_value(),"shop original native item grant planned");apply(*r);return r->items.back().after.id;};
 const auto paperId=grant({paper,0,2});const auto pouch=*catalog->CurrencyKey(CurrencyTokenMode::DynamicGold);ItemGrant award{pouch};award.currencyAmount=1;
 std::vector<PrivateShopOffer> offers;for(unsigned n=0;n<120;++n)offers.push_back({grant(award),n?1:price,static_cast<std::uint16_t>(n)});
 const auto output=[&](const std::string& phase,std::uint8_t view,PrivateShopStatus status,std::uint64_t subject=0){
  const auto& viewer=view==2?buy:state;PrivateShopSnapshot s;s.view=view;s.status=status;s.owner=seller.id;s.target=240010;s.balance=viewer.wallets[0].balance;s.revision=viewer.fence.revision;s.cap=cap;s.nowAtMs=now();s.subject=subject;s.nonce=status==PrivateShopStatus::Preview?5701:0;s.taxPercent=17;
  if(const auto h=persistence::LoadPrivateShopHeader(sql,seller.id);h && *h){s.sign=(**h).sign;s.remember=(**h).rememberPrices;}
  std::vector<PersistentItem> listed;for(const auto& i:state.items)if(view!=2 || i.privateShop)listed.push_back(i);
  if(view==0){for(const auto& i:state.items)if(PrivateShopListable(*catalog,i,seller,s.nowAtMs))s.eligible.push_back(i.id.Value());const auto prices=persistence::LoadPrivateShopPrices(sql,*catalog,seller.id);Check(prices.has_value(),"personal native-key price memory read");for(const auto& p:*prices)s.prices.push_back({p.key,p.level,p.unit});}
  if(phase=="open_preview"){s.sign="Árvíztűrő bolt";s.offers=offers;}
  const auto frame=EncodePrivateShopSnapshot(*catalog,s,state.storages,listed);Check(frame.has_value(),"actual source private shop frame encoded");const auto file=[&](const char* kind,const auto& b){std::ofstream f(path+"."+phase+"."+kind+".hex");for(auto v:b){const auto x=static_cast<unsigned char>(v);f<<"0123456789abcdef"[x>>4]<<"0123456789abcdef"[x&15];}f<<'\n';Check(f.good(),"shop frame exported");};
  file("shop",*frame);file("inventory",EncodeTypedInventory(*catalog,viewer.storages,viewer.wallets,viewer.items).value());file("details",EncodeTypedItemDetails(*catalog,viewer.items).value());++packets;
 };
 output("composer",0,PrivateShopStatus::Ready,paperId.Value());const auto open=MakePrivateShopOpen(*catalog,op(),state.fence,state.storages,state.items,state.wallets[0],paperId,"Árvíztűrő bolt",offers,now(),cap);Check(open && open->items.size()==121,"all120 actual native instances plus paper are one commit");
 auto plan=persistence::PrepareItemWrite(*catalog,*open);Check(plan.has_value() && plan->size()>512,"actual120-item SQL plan exceeds old shared transaction step budget");output("open_preview",0,PrivateShopStatus::Preview,paperId.Value());apply(*open);Check(state.items.size()==121 && state.items.front().count==1 && persistence::LoadPrivateShopHeader(sql,seller.id)->has_value(),"actual SQL opens120 listings and consumes exactly one paper");output("opened",1,PrivateShopStatus::Applied);apply(*open);Check(replay && state.items.front().count==1,"open receipt replay consumes no second paper");
 const auto h=**persistence::LoadPrivateShopHeader(sql,seller.id);auto combined=state.items;combined.insert(combined.end(),buy.items.begin(),buy.items.end());auto layouts=state.storages;layouts.insert(layouts.end(),buy.storages.begin(),buy.storages.end());auto wallets=state.wallets;wallets.insert(wallets.end(),buy.wallets.begin(),buy.wallets.end());
 const auto sale=MakePrivateShopBuy(*catalog,op(),h,state.fence,buy.fence,layouts,combined,wallets,offers[0].id,17,now(),cap);Check(sale.has_value(),"real whole-stack sale prepares exact64-bit price");
 auto secondItems=state.items;secondItems.insert(secondItems.end(),third.items.begin(),third.items.end());auto secondLayouts=state.storages;secondLayouts.insert(secondLayouts.end(),third.storages.begin(),third.storages.end());auto secondWallets=state.wallets;secondWallets.insert(secondWallets.end(),third.wallets.begin(),third.wallets.end());const auto compete=MakePrivateShopBuy(*catalog,op(),h,state.fence,third.fence,secondLayouts,secondItems,secondWallets,offers[0].id,17,now(),cap);Check(compete.has_value(),"competing buyer quote valid before first sale");
 output("buyer",2,PrivateShopStatus::Ready);output("buy_preview",2,PrivateShopStatus::Preview,offers[0].id.Value());apply(*sale);Check(buy.items.size()==1 && buy.items[0].currencyAmount==1 && !buy.items[0].privateShop && buy.wallets[0].balance==50000000000ULL-price && state.wallets[0].balance==1000+price-(price/100*17+price%100*17/100),"actual sale preserves immutable payout value and exact seller tax/buyer balance");output("bought",2,PrivateShopStatus::Applied);apply(*sale);Check(replay && buy.items.size()==1,"sale receipt replay cannot duplicate item or money");apply(*compete,false);Check(third.items.empty() && third.wallets[0].balance==50000000000ULL,"competing stale buyer retains all money");
 const auto oldSession=state.fence.sessionGeneration;std::optional<runtime::LoginLoad> login;Check(runtime::RequestLoginLoad(seller.id,[&](auto loaded){login=std::move(loaded);}),"actual login recovery queued");wait([&](){return login.has_value();});Check(login->loaded.has_value(),"new login recovers shop before publishing its inventory");state=std::move(*login->loaded);Check(state.fence.sessionGeneration>oldSession && std::ranges::none_of(state.items,[](const auto& i){return i.privateShop.has_value();}) && !persistence::LoadPrivateShopHeader(sql,seller.id)->has_value(),"new login releases119 original slots and removes stale header");Check(!persistence::RecoverPrivateShop(sql,*catalog,seller,oldSession),"late old logout cannot mutate newly claimed owner session");output("recovered",0,PrivateShopStatus::Ready,paperId.Value());
 ItemGrant silkGrant{silk};silkGrant.createdAtUtcMs=now();const auto silkId=grant(silkGrant);const auto silkItem=*std::ranges::find(state.items,silkId,&PersistentItem::id);Check(silkItem.shopPermitDeadline==silkGrant.createdAtUtcMs+864000000ULL,"actual source silk persists exact ten-day deadline");
 const std::array remembered{PrivateShopOffer{offers[1].id,17,0}};auto silkOpen=MakePrivateShopOpen(*catalog,op(),state.fence,state.storages,state.items,state.wallets[0],paperId,"Selyem bolt",remembered,now(),cap);Check(silkOpen && silkOpen->privateShop->subject==silkId.Value(),"silk automatically takes precedence over remaining paper");apply(*silkOpen);const auto cache=persistence::LoadPrivateShopPrices(sql,*catalog,seller.id);Check(cache && cache->size()==1 && (*cache)[0].key==pouch && (*cache)[0].unit==17,"personal price memory uses typed key/refinement and exact unit price");
 output("close_preview",1,PrivateShopStatus::Preview);const auto close=MakePrivateShopClose(*catalog,op(),silkOpen->privateShop->header,state.fence,state.storages,state.items);Check(close.has_value(),"silk shop close prepared");apply(*close);output("price_memory",0,PrivateShopStatus::Ready,silkId.Value());
 ItemGrant expired{silk};expired.createdAtUtcMs=now()-864000001ULL;const auto expiredId=grant(expired);auto expiry=MakePrivateShopPermitExpiry(*catalog,op(),state.fence,state.storages,state.items,expiredId,now());Check(expiry.has_value(),"elapsed original silk plans expiry");apply(*expiry);Check(std::ranges::find(state.items,expiredId,&PersistentItem::id)==state.items.end(),"expired silk tombstone removed from authoritative bag");
 // Actual transaction time defeats a request captured while a permit was valid.
 const ItemOwner late{ItemOwnerKind::Character,24004};const std::array lateLayouts{ItemStorageLayout{{late,ItemStorageKind::Inventory,1},5,9,1}};const std::array lateWallets{ItemWallet{late,WalletCurrency::Gold,1,1000}};Check(persistence::ProvisionOwner(sql,*catalog,late,lateLayouts,lateWallets).has_value(),"late request owner provisioned");auto lateState=persistence::LoadCurrentItemOwner(sql,*catalog,late).value();const auto lateNow=now()-864000001ULL;
 const std::array lateIds{ItemInstanceId::Create(++nextId).value()};expired.createdAtUtcMs=lateNow;auto issue=MakeGrantCommit(*catalog,op(),lateState.fence,lateState.storages,lateState.items,expired,lateIds).value();apply(issue);lateState=persistence::LoadCurrentItemOwner(sql,*catalog,late).value();const std::array stockIds{ItemInstanceId::Create(++nextId).value()};issue=MakeGrantCommit(*catalog,op(),lateState.fence,lateState.storages,lateState.items,award,stockIds).value();apply(issue);lateState=persistence::LoadCurrentItemOwner(sql,*catalog,late).value();const std::array lateOffer{PrivateShopOffer{stockIds[0],1,0}};const auto lateOpen=MakePrivateShopOpen(*catalog,op(),lateState.fence,lateState.storages,lateState.items,lateState.wallets[0],lateIds[0],"Elkésett",lateOffer,lateNow+1,cap);Check(lateOpen.has_value(),"request originally captured within ten-day permit lifetime");apply(*lateOpen,false);Check(!persistence::LoadPrivateShopHeader(sql,late.id)->has_value(),"actual SQL clock refuses expired queued opening without creating header");
 store.Stop();std::cout<<"SOURCE_PRIVATE_SHOP_WORKER=SUCCESS sources=2 packets="<<packets<<" checks="<<checks<<std::endl;
}
